def q(question, answer, facts, keys, confusions, category):
    return dict(question=question, referenceAnswer=answer, requiredFacts=facts,
                keys=keys, forbiddenConfusions=confusions, category=category,
                answerable=True)


def u(question, missing, confusion):
    return dict(question=question, referenceAnswer=f"文档未提供{missing}，无法据此确定。",
                requiredFacts=[f"文档未提供{missing}", "明确拒绝猜测"], keys=[],
                forbiddenConfusions=[confusion], category="unanswerable", answerable=False)


