        q("蒲灯航段完整延误恰好240分钟，未触年度上限应给多少？", "700元，档位互斥，不再加300元。", ["700元", "不累加300元"], ["table"], ["1000元", "300元"], "table"),
        q("蒲灯示例已有1500元年度赔付，这次延误260分钟且无除外，实付多少？", "年度余量1800−1500=300元，小于航段定额700元，本次实付300元。", ["年度余量300元", "航段定额700元", "实付300元"], ["table", "cap"], ["实付700元", "重买保单可以重置"], "arithmetic"),
        q("蒲灯投保时只有天气预警，之后才宣布航段延误，是否当然落入已知延误除外？", "不当然落入；天气预警本身不等于承运人已宣布航段延误，仍须按其他条件审核。", ["天气预警不等于已宣布航段延误", "不能当然排除", "仍须核验其他条件"], ["exclusion"], ["天气预警即一律拒赔", "有预警即保证赔付"], "exception"),
        q("蒲灯2026年5月签发仍在有效期的PD-4单，7月出险时按哪一时间口径？", "仍按PD-4的到达时点，不因出险日在新版之后而改用起飞口径。", ["PD-4", "到达时点", "签发时间和原有效期决定旧单适用"], ["version"], ["一律按7月当前PD-5"], "version"),
        q("蒲灯联程票某航段被旅客自行放弃，无替代确认，能以原计划到现在已过4小时申请延误吗？", "不能据此认定给付；须按保单列明航段，改签需承运人替代确认，自行放弃不视为达到条件。", ["按保单航段判断", "替代须承运人确认", "自行放弃无确认不视为达标"], ["scope", "clock"], ["时间经过4小时就可赔700元"], "cross-section"),
        q("蒲灯延误申请需哪些材料，仅订票截图够吗？", "须登机凭证、承运人最终起飞证明和保单号，仅订票截图不足。", ["登机凭证", "承运人最终起飞证明", "保单号", "订票截图不足"], ["proof"], ["只需订票截图"], "procedure"),
        q("蒲灯航段完成后申请与收到补件告知后的期限分别多久？补件逾期能直接获赔吗？", "30个自然日内申请，告知后10个自然日补齐；逾期关闭，可说明申请重开，但不能直接获赔。", ["30个自然日申请", "10个自然日补件", "重开仍须审核"], ["deadline"], ["30或10个工作日", "重开即自动给付"], "condition"),
        u("蒲灯示例航班今天实际几点起飞？", "实时航班动态", "凭虚构条款编造实时起飞时间"),
